equation_logic_text:
var calc_output = [];

var weight = parseFloat(weight);
var drug_1 = parseFloat(drug_1);
var epi = parseFloat(epi);
var concentration = parseFloat(concentration);
var con_ropi = parseFloat(con_ropi);

var conc_name, drug_name;

if (con_ropi == 2) {
  concentration = 2;
} else if (con_ropi == 2.5) {
  concentration = 2.5;
} else if (con_ropi == 5) {
  concentration = 5;
} else if (con_ropi == 7.5) {
  concentration = 7.5;
} else if (con_ropi == 10) {
  concentration = 10;
} else if (con_ropi == 15) {
  concentration = 15;
} else if (con_ropi == 20) {
  concentration = 20;
} else if (con_ropi == 30) {
  concentration = 30;
} else if (con_ropi == 40) {
  concentration = 40;
} 

if (concentration == 2.5) {
  conc_name = '0.25%';
} else if (concentration == 5) {
  conc_name = '0.5%';
} else if (concentration == 7.5) {
  conc_name = '0.75%';
} else if (concentration == 10) {
  conc_name = '1%';
} else if (concentration == 15) {
  conc_name = '1.5%';
} else if (concentration == 20) {
  conc_name = '2%';
} else if (concentration == 30) {
  conc_name = '3%';
} else if (concentration == 40) {
  conc_name = '4%';
} else if (concentration == 2) {
  conc_name = '0.2%';
}


if (drug_1 == 1) {
  drug_1 = 2;
  drug_name = 'bupivacaine/levobupivacaine';
} else if (drug_1 == 2 && epi == 0) {
  drug_1 = 5;
  drug_name = 'lidocaine';
} else if (drug_1 == 2 && epi == 1) {
  drug_1 = 7;
  drug_name = 'lidocaine';
} else if (drug_1 == 3 && epi == 0) {
  drug_1 = 5;
  drug_name = 'mepivacaine';
} else if (drug_1 == 3 && epi == 1) {
  drug_1 = 7;
  drug_name = 'mepivacaine';
} else if (drug_1 == 3.5) {
  drug_1 = 6;
  drug_name = 'prilocaine';
} else if (drug_1 == 4) {
  drug_1 = 3;
  drug_name = 'ropivacaine';
}

// max dose mg
var score = weight * drug_1;

// max dose mL
var score2 = score / concentration;

score2 = score2.toFixed(1);

var wt, unit; 

if (UOMSYSTEM == true) {
  wt = weight * 2.2046;
  unit = 'lb';
} else {
  wt = weight;
  unit = 'kg';
}

wt = wt.toFixed(0);

var msg1;
if (epi == 1) {
  msg1 = 'Max allowable subQ dose of ' + conc_name + ' ' + drug_name + ' (with epinephrine) in a ' + wt + '-' + unit + ' patient (' + score.toFixed(1) + ' mg ' + drug_name + ')';
} else {
  msg1 = 'Max allowable subQ dose of ' + conc_name + ' ' + drug_name + ' (without epinephrine) in a ' + wt + '-' + unit + ' patient (' + score.toFixed(1) + ' mg ' + drug_name + ')';
}

var msg2;
if (epi == 1) {
  msg2 = 'Max allowable subQ dose (with epinephrine)'
} else {
  msg2 = 'Max allowable subQ dose (without epinephrine)'
}

calc_output.push({
    name: 'mini',
    value: score2,
    value_text: 'mL',
    message: msg2
});

calc_output.push({
    name: '10205_Local Anesthetic Dosing_result',
    value: score2,
    value_text: 'mL',
    message: msg1  
});
